**`AddEditTaskActivity.kt`** — handles both **Add** and **Update** modes (single activity, distinguished by the presence of `EXTRA_TASK_ID`):

```kotlin
package com.example.todolist

import android.app.DatePickerDialog
import android.app.TimePickerDialog
import android.os.Bundle
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.lifecycleScope
import com.example.todolist.data.Task
import com.example.todolist.util.ReminderScheduler
import com.google.android.material.button.MaterialButton
import com.google.android.material.switchmaterial.SwitchMaterial
import com.google.android.material.textfield.TextInputEditText
import kotlinx.coroutines.launch
import java.text.SimpleDateFormat
import java.util.Calendar
import java.util.Date
import java.util.Locale

class AddEditTaskActivity : AppCompatActivity() {

    companion object {
        const val EXTRA_TASK_ID = "com.example.todolist.EXTRA_TASK_ID"
    }

    private lateinit var viewModel: TaskViewModel
    private lateinit var etTitle: TextInputEditText
    private lateinit var etDescription: TextInputEditText
    private lateinit var btnPickDateTime: MaterialButton
    private lateinit var switchReminder: SwitchMaterial

    private var editingTask: Task? = null
    private var dueDateTimeMillis: Long = 0L

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_add_edit_task)

        viewModel = ViewModelProvider(this)[TaskViewModel::class.java]

        etTitle = findViewById(R.id.etTitle)
        etDescription = findViewById(R.id.etDescription)
        btnPickDateTime = findViewById(R.id.btnPickDateTime)
        switchReminder = findViewById(R.id.switchReminder)
        val btnSave = findViewById<MaterialButton>(R.id.btnSave)

        val taskId = intent.getIntExtra(EXTRA_TASK_ID, -1)
        if (taskId != -1) {
            title = getString(R.string.edit_task)
            loadTask(taskId)
        } else {
            title = getString(R.string.add_task)
        }

        btnPickDateTime.setOnClickListener { showDateTimePicker() }
        btnSave.setOnClickListener { saveTask() }
    }

    private fun loadTask(taskId: Int) {
        lifecycleScope.launch {
            val task = viewModel.getTaskById(taskId) ?: return@launch
            editingTask = task
            dueDateTimeMillis = task.dueDateTime
            etTitle.setText(task.title)
            etDescription.setText(task.description)
            btnPickDateTime.text = formatDateTime(task.dueDateTime)
            switchReminder.isChecked = task.reminderEnabled
        }
    }

    private fun showDateTimePicker() {
        val calendar = Calendar.getInstance().apply {
            if (dueDateTimeMillis > 0) timeInMillis = dueDateTimeMillis
        }

        DatePickerDialog(
            this,
            { _, year, month, dayOfMonth ->
                TimePickerDialog(
                    this,
                    { _, hourOfDay, minute ->
                        calendar.set(year, month, dayOfMonth, hourOfDay, minute, 0)
                        calendar.set(Calendar.MILLISECOND, 0)
                        dueDateTimeMillis = calendar.timeInMillis
                        btnPickDateTime.text = formatDateTime(dueDateTimeMillis)
                    },
                    calendar.get(Calendar.HOUR_OF_DAY),
                    calendar.get(Calendar.MINUTE),
                    true
                ).show()
            },
            calendar.get(Calendar.YEAR),
            calendar.get(Calendar.MONTH),
            calendar.get(Calendar.DAY_OF_MONTH)
        ).show()
    }

    private fun saveTask() {
        val title = etTitle.text.toString().trim()
        if (title.isEmpty()) {
            etTitle.error = getString(R.string.title_required)
            etTitle.requestFocus()
            return
        }
        if (dueDateTimeMillis == 0L) {
            Toast.makeText(this, R.string.date_time_required, Toast.LENGTH_SHORT).show()
            return
        }

        val description = etDescription.text.toString().trim()
        val reminderEnabled = switchReminder.isChecked &&
                dueDateTimeMillis > System.currentTimeMillis()

        lifecycleScope.launch {
            val savedTask: Task
            val current = editingTask
            if (current != null) {
                // UPDATE
                savedTask = current.copy(
                    title = title,
                    description = description,
                    dueDateTime = dueDateTimeMillis,
                    reminderEnabled = reminderEnabled
                )
                viewModel.update(savedTask)
            } else {
                // ADD — insert first, take the generated ID back
                val newId = viewModel.insertAndGetId(
                    Task(
                        title = title,
                        description = description,
                        dueDateTime = dueDateTimeMillis,
                        reminderEnabled = reminderEnabled
                    )
                )
                savedTask = Task(
                    id = newId.toInt(),
                    title = title,
                    description = description,
                    dueDateTime = dueDateTimeMillis,
                    reminderEnabled = reminderEnabled
                )
            }

            if (savedTask.reminderEnabled) {
                ReminderScheduler.schedule(this@AddEditTaskActivity, savedTask)
            } else {
                ReminderScheduler.cancel(this@AddEditTaskActivity, savedTask.id)
            }

            Toast.makeText(this@AddEditTaskActivity, R.string.task_saved, Toast.LENGTH_SHORT).show()
            finish()
        }
    }

    private fun formatDateTime(millis: Long): String =
        SimpleDateFormat("EEE, dd MMM yyyy 'at' hh:mm a", Locale.getDefault()).format(Date(millis))
}
